package repo

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/google/uuid"

	"github.com/peaky-team/peaky/services/internal/authz"
	syncdb "github.com/peaky-team/peaky/services/internal/syncengine/db"
)

// PostgresSyncRepo implements SyncRepo against a PostgreSQL database.
//
// Simple queries (GetFieldVersion, UpsertFieldVersion, GetCursor, SaveCursor,
// FindAttachmentReview) are generated by sqlc from
// internal/syncengine/repo/queries.sql. Run `make gen:sqlc` after editing that file.
//
// Two queries are hand-written because sqlc cannot express them statically:
//   - pullEventRows — variable-length entity_id IN clause
//   - attachFields  — variable-length event_id/entity tuple filters
type PostgresSyncRepo struct {
	db      *sql.DB
	queries *syncdb.Queries
}

// NewPostgresSyncRepo constructs a production SyncRepo.
func NewPostgresSyncRepo(db *sql.DB) *PostgresSyncRepo {
	return &PostgresSyncRepo{
		db:      db,
		queries: syncdb.New(db),
	}
}

var _ SyncRepo = (*PostgresSyncRepo)(nil)

// PostgresSyncRepo is also the server-side review-participants lookup behind
// the Advisor override policy (authorization/REQ-008; AC-024).
var _ authz.ReviewParticipantLookup = (*PostgresSyncRepo)(nil)

// GetFieldVersion returns the current winning field version, or nil if none exists.
func (r *PostgresSyncRepo) GetFieldVersion(ctx context.Context, entityType, entityID, fieldName string) (*FieldVersion, error) {
	row, err := r.queries.GetFieldVersion(ctx, syncdb.GetFieldVersionParams{
		EntityType: entityType,
		EntityID:   entityID,
		FieldName:  fieldName,
	})
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("get field version: %w", err)
	}
	fv := &FieldVersion{
		EntityType: row.EntityType,
		EntityID:   row.EntityID,
		FieldName:  row.FieldName,
		HLC:        row.Hlc,
		ActorID:    row.ActorID,
	}
	if row.Value.Valid {
		fv.Value = &row.Value.String
	}
	return fv, nil
}

// UpsertFieldVersion writes or overwrites a field version.
func (r *PostgresSyncRepo) UpsertFieldVersion(ctx context.Context, fv FieldVersion) error {
	var value sql.NullString
	if fv.Value != nil {
		value = sql.NullString{String: *fv.Value, Valid: true}
	}
	err := r.queries.UpsertFieldVersion(ctx, syncdb.UpsertFieldVersionParams{
		ID:         uuid.New().String(),
		EntityType: fv.EntityType,
		EntityID:   fv.EntityID,
		FieldName:  fv.FieldName,
		Value:      value,
		Hlc:        fv.HLC,
		ActorID:    fv.ActorID,
		UpdatedAt:  time.Now().UTC(),
	})
	if err != nil {
		return fmt.Errorf("upsert field version: %w", err)
	}
	return nil
}

// GetCursor returns the latest sync cursor for the actor, or "" if none.
func (r *PostgresSyncRepo) GetCursor(ctx context.Context, actorID string) (string, error) {
	cursor, err := r.queries.GetCursor(ctx, actorID)
	if errors.Is(err, sql.ErrNoRows) {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("get cursor: %w", err)
	}
	return cursor, nil
}

// SaveCursor persists an actor's sync cursor.
func (r *PostgresSyncRepo) SaveCursor(ctx context.Context, actorID, cursor string) error {
	err := r.queries.SaveCursor(ctx, syncdb.SaveCursorParams{
		ActorID:     actorID,
		CursorValue: cursor,
		UpdatedAt:   time.Now().UTC(),
	})
	if err != nil {
		return fmt.Errorf("save cursor: %w", err)
	}
	return nil
}

// PullEvents returns events after the cursor, scoped to the actor's
// root-level entitlements (root_type/root_id), with each event's accepted
// field values attached from field_version_events.
//
// Two-query strategy:
//  1. Fetch paginated events (fast, uses time index).
//  2. Batch-fetch field_version_events for every event id in the result set.
//
// The field values returned are the values accepted for that specific event.
// This lets a fresh client replay history frame-by-frame and lets Recent
// Changes show intermediate transitions instead of the final value repeated
// for every event in the pull window.
func (r *PostgresSyncRepo) PullEvents(ctx context.Context, actorID, after string, scope PullScope, limit int) ([]PullEvent, bool, error) {
	events, hasMore, err := r.pullEventRows(ctx, after, scope, limit)
	if err != nil {
		return nil, false, err
	}
	if len(events) > 0 {
		if err := r.attachFields(ctx, events); err != nil {
			return nil, false, err
		}
	}
	return events, hasMore, nil
}

// zeroTime is the default lower bound when no cursor is provided.
// PostgreSQL rejects an empty string as a TIMESTAMPTZ literal, so we use
// the Unix epoch instead of passing "".
const zeroTime = "1970-01-01T00:00:00Z"

// parseCursor splits a composite "time:id" cursor into its parts, falling
// back to a legacy timestamp-only cursor (afterID == "") or no cursor at all
// (afterTime == zeroTime). Shared by every SyncRepo implementation so the
// composite-cursor tuple semantics — (time, id) > (afterTime, afterID) —
// can never drift between the Postgres and fake repos.
func parseCursor(after string) (afterTime, afterID string) {
	afterTime = after
	if after != "" && !isCursorTime(after) {
		for i := 1; i < len(after); i++ {
			if after[i] != ':' {
				continue
			}
			if isCursorTime(after[:i]) && i+1 < len(after) {
				afterTime = after[:i]
				afterID = after[i+1:]
				break
			}
		}
	}
	if afterTime == "" {
		afterTime = zeroTime
	}
	return afterTime, afterID
}

// pullEventRows fetches the raw event rows without field data.
// Hand-written: sqlc cannot express a variable-length tuple IN clause or
// ANY() array comparison statically.
func (r *PostgresSyncRepo) pullEventRows(ctx context.Context, after string, scope PullScope, limit int) ([]PullEvent, bool, error) {
	afterTime, afterID := parseCursor(after)

	// Empty scope: no access to anything. Return zero events — the inverse
	// of the old "entitled=nil fetches everything" bug (#53).
	if scope.IsEmpty() {
		return nil, false, nil
	}

	// Build the root-based WHERE clause:
	//   root_type = ANY($wildcards) OR (root_type, root_id) IN ($exactRefs)
	var args []any
	args = append(args, afterTime) // $1
	idx := 2                       // next placeholder

	var whereParts []string

	if len(scope.Wildcards) > 0 {
		args = append(args, scope.Wildcards)
		whereParts = append(whereParts, fmt.Sprintf("root_type = ANY($%d)", idx))
		idx++
	}

	if len(scope.ExactRefs) > 0 {
		placeholders := make([]string, len(scope.ExactRefs))
		for i, ref := range scope.ExactRefs {
			placeholders[i] = fmt.Sprintf("($%d,$%d)", idx, idx+1)
			args = append(args, ref.RootType, ref.RootID)
			idx += 2
		}
		whereParts = append(whereParts, fmt.Sprintf("(root_type, root_id) IN (%s)", strings.Join(placeholders, ",")))
	}

	rootFilter := strings.Join(whereParts, " OR ")

	var q string
	if afterID != "" {
		args = append(args, afterID, limit+1)
		q = fmt.Sprintf(`
			SELECT id, entity_type, entity_id, actor_id, time, operation
			FROM events
			WHERE (time, id) > ($1, $%d)
			  AND entity_type IS NOT NULL
			  AND (%s)
			ORDER BY time ASC, id ASC
			LIMIT $%d`, idx, rootFilter, idx+1)
	} else {
		args = append(args, limit+1)
		q = fmt.Sprintf(`
			SELECT id, entity_type, entity_id, actor_id, time, operation
			FROM events
			WHERE time > $1
			  AND entity_type IS NOT NULL
			  AND (%s)
			ORDER BY time ASC, id ASC
			LIMIT $%d`, rootFilter, idx)
	}

	rows, err := r.db.QueryContext(ctx, q, args...)
	if err != nil {
		return nil, false, fmt.Errorf("pull events: %w", err)
	}
	defer func() { _ = rows.Close() }()

	var events []PullEvent
	for rows.Next() {
		var ev PullEvent
		var t time.Time
		if err := rows.Scan(&ev.ID, &ev.EntityType, &ev.EntityID, &ev.ActorID, &t, &ev.Operation); err != nil {
			return nil, false, fmt.Errorf("scan pull event: %w", err)
		}
		ev.Time = t.UTC().Format(time.RFC3339Nano)
		events = append(events, ev)
	}
	if err := rows.Err(); err != nil {
		return nil, false, fmt.Errorf("pull events rows: %w", err)
	}

	hasMore := len(events) > limit
	if hasMore {
		events = events[:limit]
	}
	return events, hasMore, nil
}

func isCursorTime(value string) bool {
	if _, err := time.Parse(time.RFC3339Nano, value); err == nil {
		return true
	}
	if _, err := time.Parse(time.RFC3339, value); err == nil {
		return true
	}
	return false
}

// attachFields batch-fetches field_version_events for all event ids and
// attaches the historical field values to their owning event.
//
// value::text casts the JSONB column to its canonical JSON text form — the same
// representation that was written during push (JSON-encoded string, number, etc.).
func (r *PostgresSyncRepo) attachFields(ctx context.Context, events []PullEvent) error {
	if len(events) == 0 {
		return nil
	}

	eventPlaceholders := make([]string, len(events))
	args := make([]any, 0, len(events))
	for i, ev := range events {
		eventPlaceholders[i] = fmt.Sprintf("$%d", i+1)
		args = append(args, ev.ID)
	}

	//nolint:gosec // eventPlaceholders contains only "$N" positional params, not user input.
	q := fmt.Sprintf(`
		SELECT event_id, field_name, value::text, hlc
		FROM field_version_events
		WHERE event_id IN (%s)
		ORDER BY updated_at ASC, id ASC`, strings.Join(eventPlaceholders, ","))

	rows, err := r.db.QueryContext(ctx, q, args...)
	if err != nil {
		return fmt.Errorf("fetch field version events: %w", err)
	}
	defer func() { _ = rows.Close() }()

	fieldMap := make(map[string][]FieldValue, len(events))
	for rows.Next() {
		var eventID, fieldName, hlc string
		var value sql.NullString
		if err := rows.Scan(&eventID, &fieldName, &value, &hlc); err != nil {
			return fmt.Errorf("scan field version event: %w", err)
		}
		fv := FieldValue{Name: fieldName, HLC: hlc}
		if value.Valid {
			fv.Value = &value.String
		}
		fieldMap[eventID] = append(fieldMap[eventID], fv)
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("field version events rows: %w", err)
	}

	missingCurrentFallback := make([]PullEvent, 0, len(events))
	for i := range events {
		if fields := fieldMap[events[i].ID]; len(fields) > 0 {
			events[i].Fields = fields
		} else {
			missingCurrentFallback = append(missingCurrentFallback, events[i])
		}
	}

	if len(missingCurrentFallback) > 0 {
		if err := r.attachCurrentFieldsFallback(ctx, events, missingCurrentFallback); err != nil {
			return err
		}
	}
	return nil
}

// attachCurrentFieldsFallback preserves pre-migration events that have no
// field_version_events rows. Those events cannot recover historical values, so
// they receive the current field_versions snapshot instead of an empty payload.
func (r *PostgresSyncRepo) attachCurrentFieldsFallback(ctx context.Context, events []PullEvent, fallback []PullEvent) error {
	type pair struct{ entityType, entityID string }
	seen := make(map[pair]bool, len(fallback))
	var pairs []pair
	for _, ev := range fallback {
		p := pair{ev.EntityType, ev.EntityID}
		if !seen[p] {
			seen[p] = true
			pairs = append(pairs, p)
		}
	}

	placeholders := make([]string, len(pairs))
	args := make([]any, 0, len(pairs)*2)
	for i, p := range pairs {
		placeholders[i] = fmt.Sprintf("($%d,$%d)", i*2+1, i*2+2)
		args = append(args, p.entityType, p.entityID)
	}

	//nolint:gosec // placeholders contains only "($N,$M)" positional params, not user input.
	q := fmt.Sprintf(`
		SELECT entity_type, entity_id, field_name, value::text, hlc, actor_id
		FROM field_versions
		WHERE (entity_type, entity_id) IN (%s)
		ORDER BY field_name ASC`, strings.Join(placeholders, ","))

	rows, err := r.db.QueryContext(ctx, q, args...)
	if err != nil {
		return fmt.Errorf("fetch fallback field versions: %w", err)
	}
	defer func() { _ = rows.Close() }()

	fieldMap := make(map[pair][]FieldValue, len(pairs))
	for rows.Next() {
		var entityType, entityID, fieldName, hlc, actorID string
		var value sql.NullString
		if err := rows.Scan(&entityType, &entityID, &fieldName, &value, &hlc, &actorID); err != nil {
			return fmt.Errorf("scan fallback field version: %w", err)
		}
		key := pair{entityType, entityID}
		fv := FieldValue{Name: fieldName, HLC: toWireHLC(hlc, actorID)}
		if value.Valid {
			fv.Value = &value.String
		}
		fieldMap[key] = append(fieldMap[key], fv)
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("fallback field versions rows: %w", err)
	}

	for i := range events {
		key := pair{events[i].EntityType, events[i].EntityID}
		if len(events[i].Fields) == 0 {
			events[i].Fields = fieldMap[key]
		}
	}
	return nil
}

func toWireHLC(hlc, actorID string) string {
	if strings.Count(hlc, ":") == 1 {
		return hlc + ":" + actorID
	}
	return hlc
}

// SaveEvent persists an accepted sync event.
func (r *PostgresSyncRepo) SaveEvent(ctx context.Context, ev SyncEvent) error {
	t, err := time.Parse(time.RFC3339Nano, ev.PushedAt)
	if err != nil {
		t, err = time.Parse(time.RFC3339, ev.PushedAt)
		if err != nil {
			return fmt.Errorf("save event: parse time: %w", err)
		}
	}

	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("save event: begin transaction: %w", err)
	}
	defer func() { _ = tx.Rollback() }()

	_, err = tx.ExecContext(ctx, `
		INSERT INTO events
		    (id, specversion, event_type, actor_type, actor_id, time, status, source, entity_type, entity_id, root_type, root_id, operation)
		VALUES ($1, '1.0', 'SyncEvent.v1', 'user', $2, $3, 'synced', 'peaky.sync', $4, $5, $6, $7, $8)
		ON CONFLICT (id) DO NOTHING`,
		ev.ID, ev.ActorID, t, ev.EntityType, ev.EntityID, ev.RootType, ev.RootID, ev.Operation)
	if err != nil {
		return fmt.Errorf("save event metadata: %w", err)
	}

	for _, field := range ev.Fields {
		var value any
		if field.Value != nil {
			value = *field.Value
		}
		_, err = tx.ExecContext(ctx, `
			INSERT INTO field_version_events
			    (id, event_id, entity_type, entity_id, field_name, value, hlc, actor_id, updated_at)
			VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
			ON CONFLICT (event_id, field_name) DO NOTHING`,
			uuid.New().String(), ev.ID, ev.EntityType, ev.EntityID, field.Name, value, field.HLC, ev.ActorID, t)
		if err != nil {
			return fmt.Errorf("save field version event %s: %w", field.Name, err)
		}
	}

	if err := tx.Commit(); err != nil {
		return fmt.Errorf("save event commit: %w", err)
	}
	return nil
}

// FindAttachmentReview returns the review_id for an attachment row.
// Returns sql.ErrNoRows if the attachment does not exist.
func (r *PostgresSyncRepo) FindAttachmentReview(ctx context.Context, attachmentID string) (string, error) {
	reviewID, err := r.queries.FindAttachmentReview(ctx, attachmentID)
	if err != nil {
		return "", fmt.Errorf("find attachment review %s: %w", attachmentID, err)
	}
	return reviewID, nil
}

// ParticipantRole returns the actor's current persisted review-participant
// role ('assessor' | 'reviewer'), or "" when the actor has no current
// participant row on the review. This is the server-side participants lookup
// behind the action-specific Advisor override policy (authorization/REQ-008;
// AC-024) — it satisfies authz.ReviewParticipantLookup.
func (r *PostgresSyncRepo) ParticipantRole(ctx context.Context, reviewID, actorID string) (string, error) {
	role, err := r.queries.GetReviewParticipantRole(ctx, syncdb.GetReviewParticipantRoleParams{
		ReviewID: reviewID,
		ActorID:  actorID,
	})
	if errors.Is(err, sql.ErrNoRows) {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("get review participant role: %w", err)
	}
	return role, nil
}

// ── Notifier ──────────────────────────────────────────────────────────────────

// PostgresNotifier implements Notifier via pg_notify().
// Hand-written: the pg_notify() function call does not map to a schema table,
// so sqlc drift detection does not apply here.
type PostgresNotifier struct {
	db *sql.DB
}

// NewPostgresNotifier creates a Notifier backed by the given *sql.DB.
func NewPostgresNotifier(db *sql.DB) *PostgresNotifier {
	return &PostgresNotifier{db: db}
}

var _ Notifier = (*PostgresNotifier)(nil)

// Notify calls pg_notify(channel, payload) on the database.
func (n *PostgresNotifier) Notify(ctx context.Context, channel, payload string) error {
	_, err := n.db.ExecContext(ctx, `SELECT pg_notify($1, $2)`, channel, payload)
	if err != nil {
		return fmt.Errorf("pg_notify(%s): %w", channel, err)
	}
	return nil
}

// NoopNotifier is a Notifier that does nothing — used in unit tests.
type NoopNotifier struct{}

var _ Notifier = NoopNotifier{}

func (NoopNotifier) Notify(_ context.Context, _, _ string) error { return nil }
